import fs from "node:fs";

const postsPath = "src/data/posts.ts";
const entry = fs.readFileSync("artifacts/_post-entry-tmp.ts.txt", "utf8");
let s = fs.readFileSync(postsPath, "utf8");
if (s.includes('id: "energy-systems-concentration-2026q3"')) {
  console.log("already present");
  process.exit(0);
}
const needle = "export const samplePosts: Post[] = [\n";
const i = s.indexOf(needle);
if (i < 0) throw new Error("needle missing");
s = s.slice(0, i + needle.length) + entry + s.slice(i + needle.length);
fs.writeFileSync(postsPath, s);
console.log("inserted ok");

