                  <Area
                    type="monotone"
                    dataKey="sharePct"
                    name="Cumulative %"
                    fill={ROSE}
                    fillOpacity={0.2}
                    stroke={ROSE}
                    strokeWidth={2}
                  />
                  {showEqual && (
                    <Line
                      type="monotone"
                      dataKey="equalPct"
                      name="Equal share"
                      stroke={TEAL}
                      strokeDasharray="4 4"
