          >
            <div className="mb-3">
              <ToggleGroup
                label="Series"
                value={slopeMetric}
                options={[
                  { id: "elecTop1Pct", label: "Elec" },
                  { id: "lngTop1Pct", label: "LNG" },
                  { id: "demandTop1Pct", label: "TPES" },
