                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="short" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} unit="%" />
                  <Tooltip formatter={(v) => fmtPct(Number(v), 1)} />
                  <Line
                    type="monotone"
                    dataKey="elecTop1Pct"
                    name="Elec Top-1"
                    stroke={ROSE}
                    strokeWidth={2}
                    dot={{ r: 4 }}
                  />
                  <Line
                    type="monotone"
                    dataKey="lngTop1Pct"
                    name="LNG Top-1"
                    stroke={SKY}
                    strokeWidth={2}
                    dot={{ r: 4 }}
                  />
                  <Line
                    type="monotone"
                    dataKey="demandTop1Pct"
                    name="TPES Top-1"
                    stroke={AMBER}
                    strokeWidth={2}
                    dot={{ r: 4 }}
                  />
                  <Line
                    type="monotone"
                    dataKey="solarMfgTop1Pct"
                    name="Solar mfg"
                    stroke={TEAL}
                    strokeWidth={2}
                    strokeDasharray="4 4"
                    dot={{ r: 4 }}
